import { prisma } from "@/lib/prisma/client";
import { requireAdmin } from "@/lib/auth/session";
export const dynamic="force-dynamic";
export default async function VendorPerformancePage(){await requireAdmin();const rows=await prisma.vendor.findMany({where:{evaluations:{some:{}}},select:{id:true,name:true,vendorCode:true,evaluations:{orderBy:{evaluationDate:"desc"},take:1,select:{overallScore:true,evaluationDate:true,quality:true,delivery:true}}},take:50});rows.sort((a,b)=>Number(b.evaluations[0]?.overallScore??0)-Number(a.evaluations[0]?.overallScore??0));return <main className="page"><div className="page-head"><div><div className="eyebrow">Supply intelligence</div><h1>Vendor performance</h1></div></div><section className="table-card"><table><thead><tr><th>Vendor</th><th>Code</th><th>Overall</th><th>Quality</th><th>Delivery</th><th>Evaluated</th></tr></thead><tbody>{rows.map(v=>{const score=v.evaluations[0];return <tr key={v.id}><td>{v.name}</td><td>{v.vendorCode}</td><td>{score?.overallScore.toString()||"—"}</td><td>{score?.quality||"—"}</td><td>{score?.delivery||"—"}</td><td>{score?.evaluationDate.toLocaleDateString("en-IN")||"—"}</td></tr>})}{rows.length===0&&<tr><td colSpan={6}>No vendor evaluations found.</td></tr>}</tbody></table></section></main>}
